})}
async function loadWorkScope(){await refreshDraft(true)}
async function changeSource(value){if(!canChangePreparation())return;if(sourceIDs.value.length&&!await confirmDelivery('切换来源需重新核对范围，兼容制品仍保留。继续？'))return;delete request.value.skipped_nodes;request.value.preparation_run_id=0;request.value.preparation_client_id='';workflowReady.value=false;request.value.source_type=value;request.value.version_id=0;request.value.work_item_ids=[];request.value.selected_change_ids=null;request.value.source_change_ids=null;request.value.code_confirmed=false;request.value.code_preparation_id='';request.value.order_confirmed=false;generated.value=null;availableChanges.value=[];workScope.value=null;request.value.nodes=[];binding.value=null}
watch(()=>JSON.stringify(request.value.artifacts),()=>{request.value.code_confirmed=false})
async function pinArtifacts(){await task(async()=>{
  if(existingApps.value.length&&!codeConfirmed.value)return toast('请先人工确认已有制品覆盖本版本代码变更','warning')
  binding.value=await api('api/release-versions/'+request.value.version_id+'/artifacts',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({environment:request.value.environment,bindings:appNames.value.map(service=>({service,artifact_id:request.value.artifacts[service],code_confirmed:true}))})})
  preview.value=null;toast('版本制品已关联；首次提交后锁定，后续环境复用','success')
})}
async function usePreparedCode(value){request.value.code_preparation_id=value.id;const artifacts={...request.value.artifacts,...value.artifacts};await loadCandidates();request.value.artifacts=artifacts;preview.value=null;toast('本次构建制品已关联；可继续核对已有制品并预检','success')}
function invalidatePreparedCode(){request.value.code_preparation_id='';for(const name of buildApps.value)delete request.value.artifacts[name];preview.value=null}
async function locateBlocker(message){
 const id=message.match(/#(\d+)/)?.[1],app=appNames.value.find(n=>message.includes(n))
 const resourceChange=scopeChanges.value.find(change=>String(change.id)===id&&!['code','artifact'].includes(change.kind))
 if(resourceChange){phase.value=2;await nextTick();await resourceContent.value?.reveal([resourceChange.id]);return}
 let selector
 if(id&&availableChanges.value.some(c=>String(c.id)===id)){phase.value=1;selector='[data-change-id="'+id+'"]'}
 else if(app){phase.value=2;selector='[data-artifact-app="'+app+'"]'}
 else if(message.includes('顺序')||message.includes('制品')||message.includes('代码')){phase.value=2;selector='.step-section'}
 else if(message.includes('原因')){phase.value=1;selector='[data-field="reason"]'}
 else return
 fieldIssue.value=id?'change:'+id:app?'artifact:'+app:'field'
 await nextTick();const target=document.querySelector(selector);target?.scrollIntoView({block:'nearest',behavior:'instant'});const control=target?.querySelector('input,button');focusControl(control)
}
async function resolve(){await task(async()=>{
  if(request.value.max_active_nodes!=null && !(Number.isSafeInteger(request.value.max_active_nodes)&&request.value.max_active_nodes>=1))return toast('节点并发上限请填写正整数，或留空使用原调度规则','warning')
  if(workflowReady.value&&preparedContinuation.value?.preparation){await continuationScope.value?.refresh();if(completedScopeState.value.error||completedScopeState.value.loading||completedScopeState.value.review?.changed||!completedScopeState.value.review)return toast('当前交付范围需要重新核对，请查看本页范围差异后重新准备','warning')}
  if(workflowHasPreparation.value&&!workflowReady.value)return toast('请先在本页完成范围确认与代码准备','warning')
  if(request.value.nodes.some(n=>n.kind==='approval'&&!n.approvers?.length))return toast('目标环境未配置审核人员，请通过环境审核设置配置后再预检','warning')
  if(request.value.source_type==='version'&&appNames.value.length&&!mappingMatches.value) return toast('请先核对并关联版本制品','warning')
  const input=JSON.stringify(request.value), result=await post('api/delivery/preview',JSON.parse(input))
  if(input!==JSON.stringify(request.value))return
  preview.value=result;previewInput.value=input;now.value=Date.now();phase.value=3;preflightAttempted.value=true;if(result.blockers?.length){toast(result.blockers[0],'error');if(!result.checklist?.length)await locateBlocker(result.blockers[0])}
})}
async function submit(publish=false){await task(async()=>{
  if(!previewFresh.value)return toast('请重新预检后提交','warning')
  const submittedDraftKey=draftStorageKey()
  const result=await post(publish?'api/delivery/publications':'api/delivery/runs',{...clone(request.value),preflight_token:preview.value.preflight_token})
  try{sessionStorage.removeItem(submittedDraftKey)}catch{}
  request.value={execution_mode:'dependencies',strategy_kind:'standard',template_id:0,version_id:0,source_type:'work_items',selected_change_ids:null,environment:'',reason:'',artifacts:{},nodes:[]};generated.value=null;availableChanges.value=[];preview.value=null
  await loadList();await openDetail(result);await nextTick()
  try{sessionStorage.removeItem(submittedDraftKey)}catch{}
  toast(publish?'已按本次清单提交发布，可在当前执行单查看进度':'执行单已冻结，等待审批或启动','success')
})}
async function refreshDetail(){
  const id=selected.value?.id, sequence=detailSeq
  if(!id)return
  const [run,ctrl,nacos,redis,observed]=await Promise.all([api('api/delivery/runs/'+id),api('api/delivery/runs/'+id+'/control'),api('api/nacos-executions?run_id='+id),api('api/redis-executions?run_id='+id),api('api/delivery/runs/'+id+'/observations')])
  const prep=run.plan?.preparation_run_id?await api('api/delivery/preparations/runs/'+run.plan.preparation_run_id):null
  const entries=await Promise.all([...new Set((run.steps||[]).flatMap(s=>[s.release_id,...(s.previous_release_ids||[])]).filter(Boolean))].map(async id=>[id,await api('api/releases/'+id)]))
  if(sequence!==detailSeq||selected.value?.id!==id||screen.value!=='detail')return
  selected.value=run;observations.value=observed;preparationSummary.value=prep;control.value=ctrl;nacosExecutions.value=nacos;redisExecutions.value=redis;children.value=Object.fromEntries(entries);pollError.value=''
}
async function openDetail(run){
  if(run.preparation){await router.replace({path:'/orchestration',query:{preparation:String(run.id)}});await restorePreparation(run.id);return}
  if(screen.value==='list')listScroll=window.scrollY
  ++detailSeq;selected.value={id:run.id};screen.value='detail';nodeIndex.value=0;detailTab.value='progress';logRelease.value=0;recoveryDraft.value=null
  try{await refreshDetail();nodeIndex.value=focusStep(selected.value.steps||[],statusOf);await router.replace({path:'/orchestration',query:{run:String(run.id)}})}catch(e){toast(e.message,'error');screen.value='list';selected.value=null}
}
async function back(){
  if(!await canLeavePage())return
  if(screen.value==='template'){screen.value=returnScreen;return}
  if(screen.value==='prepare')try{sessionStorage.removeItem(draftStorageKey())}catch{}
  ++detailSeq;logRelease.value=0;screen.value='list';selected.value=null
  router.replace({path:'/orchestration',query:sourceWorkItem?sourceWorkItemIDs.length>1?{work_items:sourceWorkItemIDs.join(',')}:{work_item:String(sourceWorkItem)}:sourceVersion?{version:String(sourceVersion)}:{}})
  requestAnimationFrame(()=>window.scrollTo(0,listScroll));loadList()
}
async function action(op){await task(async()=>{
  const run=selected.value, next=activeStep.value, manual=next?.kind==='manual', graph=run.plan.execution_mode==='dependencies'
  const body={digest:run.digest,node_id:op==='advance'?(graph?next?.node_id:manual?next.node_id:undefined):reviewNode.value?.id,comment:reviewComment.value,confirm_manual:manual}
  if(graph&&op==='advance'){body.revision=run.revision;body.service=next?.service||''}
  if(op==='advance'&&!await confirmDelivery(manual?'确认已完成「'+next.name+'」的操作？':next?'执行或核对「'+next.name+'」？':'核对本单剩余步骤及完成状态？'))return
  await post('api/delivery/runs/'+run.id+'/'+op,body)
  await refreshDetail();reviewComment.value='';if(['approve','reject'].includes(op))nodeIndex.value=Math.max(0,selected.value.steps.findIndex(s=>s.status!=='success'))
})}
async function coordinate(op){await task(async()=>{
  if(!await confirmDelivery(op==='start'?'启动自动推进？按已确认的步骤与依赖推进，人工节点由指定人员处理。已配置的监控达标后会自动继续批次，无有效指标则暂停。审批通过不会自动启动。':'暂停后续节点？当前已启动的操作不会被强制终止。',op==='start'?'启动自动推进':'暂停后续步骤',{confirmButtonText:op==='start'?'确认启动':'确认暂停'}))return
