async function rollback(step){await task(async()=>{
  const reason=rollbackReasons.value[step.release_id]?.trim()||'';if(selectedReasonRequired.value&&!reason)return toast('请填写恢复原因','warning')
  const run=selected.value
  const candidate=await api('api/delivery/runs/'+run.id+'/rollback-candidate?release_id='+step.release_id)
  if(!await confirmDelivery('生成 '+step.service+' 回退到 '+candidate.version+' 的交付草稿？只保存编排，不立即执行；须重新预检和审核。'))return
  await recoveryTemplate(run,[{id:randomUUID().slice(0,20),kind:'deploy',name:'回退 '+step.service,service:step.service}],[step.service],{[step.service]:candidate.artifact_id},'回退交付 #'+run.id+' / 子发布 '+releaseOrderLabel(children.value[step.release_id]||{id:step.release_id})+(reason?'：'+reason:''))
  toast('回退草稿已生成；请核对当前目标后预检提交','success')
