function resetPage(){filters.value.page=1}
let lastListPoll=0,lastDetailPoll=0
async function tick(){
  now.value=Date.now()
  if(mounted&&!busy.value&&!reading.value&&!document.hidden&&screen.value==='list'&&area.value==='runs'&&now.value-lastListPoll>5000){lastListPoll=now.value;await loadList(true);return}
  if(!mounted||polling||busy.value||document.hidden||screen.value!=='detail'||!selected.value?.plan)return
  if(now.value-lastDetailPoll<5000)return
  lastDetailPoll=now.value
  polling=true
  try{await refreshDetail();if(logRelease.value)await showLogs(logRelease.value,logs.value.page)}catch(e){pollError.value='状态暂未更新：'+e.message}finally{polling=false}
}
onMounted(async()=>{
  window.addEventListener('keydown',keyboard)
  window.addEventListener('beforeunload',beforeUnload)
  try{me.value=await api('/api/me');viewMemory=browserView('deploy:executions',me.value.username);filters.value=viewMemory.read(viewDefaults);await load();if(route.query.area==='templates')area.value='templates';if(route.query.preparation){await restorePreparation(Number(route.query.preparation));mounted=true}else if(route.query.run){mounted=true;await openDetail({id:Number(route.query.run)})}else if(!route.query.area&&restoreDraft()){
   await loadEnvironmentDefaults(false)
   const restoredOrder=await refreshDraft(false)
   mounted=true
   if(restoredOrder===true)toast('已恢复本窗口的交付草稿和步骤顺序，请重新预检','success')
   else if(restoredOrder===false)toast('已恢复交付范围；步骤已按当前变更和环境策略重新生成，请核对顺序','info')
  }else{mounted=true;if(route.query.start==='1'||sourceVersion||sourceWorkItem||sourceChanges.length)startDelivery()}}catch(e){mounted=true;toast(e.message,'error')}
  timer=setInterval(tick,2000)
})
onBeforeUnmount(()=>{if(window.parent!==window)window.parent.postMessage({type:'workspace.dirty',dirty:false,busy:false},location.origin);mounted=false;++draftSeq;++detailSeq;++candidateSeq;++listSeq;clearInterval(timer);clearTimeout(filterTimer);window.removeEventListener('keydown',keyboard);window.removeEventListener('beforeunload',beforeUnload)})

