.preparation-overview h3{margin:0 0 4px}
.preparation-layout{display:grid;grid-template-columns:minmax(0,1fr) minmax(300px,360px);gap:20px;align-items:start;min-width:0}
.application-preparation,.preparation-sidebar{min-width:0}
.application-preparation .checkbox,.preparation-sidebar .checkbox{white-space:normal;align-items:flex-start;overflow-wrap:anywhere}
.preparation-steps .approval-settings{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:12px}
.application-heading{display:flex;align-items:center;gap:12px;min-width:0;flex-wrap:wrap}
.application-heading b{overflow-wrap:anywhere}
.artifact-source{display:grid;grid-template-columns:minmax(0,1fr);gap:6px;margin-bottom:12px}
.artifact-row label{display:block;margin-bottom:6px}
.artifact-row small{font-size:.75rem;color:var(--muted-foreground)}
.application-preparation :deep(.code-preparation){margin-top:16px}
.preparation-sidebar{display:grid;gap:16px}
.preparation-sidebar>.platform-collapse,.preparation-steps :deep(.node-edit){margin:0}
.preparation-steps :deep(.node-editor){display:grid;gap:8px}
.preparation-steps :deep(.node-fields){grid-template-columns:minmax(0,1fr)}
.preparation-steps :deep(.node-name){max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.preparation-steps :deep(.summary-tools){display:inline-flex;flex-wrap:nowrap;align-items:center}
.preparation-sidebar li{overflow-wrap:anywhere}
@media(max-width:1100px){.preparation-layout{grid-template-columns:minmax(0,1fr)}}
@media(max-width:650px){.preparation-overview{align-items:flex-start;flex-wrap:wrap}.application-heading{gap:4px}}</style>

<style scoped>.delivery-content-body{min-width:0}.delivery-content-heading{margin:0 0 10px;font-size:.875rem}.delivery-resource-groups:not(:empty){margin-top:20px}.delivery-content-body>.delivery-resource-groups:first-child{margin-top:0}</style>
